Source example: get city from the request and return it; no read mechanism or model visibility is specified:

{
  "entry_block_ref": "acquire",
  "declared_context_keys": [
    "request"
  ],
  "blocks": [
    {
      "block_ref": "acquire",
      "block_name": "Get city from the request",
      "data_source_kind": "context",
      "instructions": [
        {
          "instruction_ref": "acquire_city",
          "opcode": "read_city_from_request",
          "inputs": [
            {
              "type": "context_key",
              "identifier": "request"
            }
          ],
          "outputs": [
            {
              "type": "result",
              "identifier": "acquired_city"
            }
